	\module.incrObjectFieldByBulk = async function (data) {
		// Validate input shape
		if (!Array.isArray(data)) {
			throw new TypeError('Expected an array as input data');
		}

		// Empty array is a no-op
		if (data.length === 0) {
			return;
		}

		// Validate each entry and prepare updates
		const validatedUpdates = [];

		for (const item of data) {
			// Validate tuple shape
			if (!Array.isArray(item) || item.length !== 2) {
				throw new TypeError('Each entry must be a [key, increments] tuple');
			}

			const [key, increments] = item;

			// Validate key
			if (typeof key !== 'string' || !key) {
				throw new TypeError('Key must be a non-empty string');
			}

			// Validate increments is an object
			if (increments === null || typeof increments !== 'object' || Array.isArray(increments)) {
				throw new TypeError('Increments must be a plain object');
			}

			// Validate fields and increment values
			const incObject = {};
			for (const [field, value] of Object.entries(increments)) {
				// Convert field to string
				const f = String(field);

				// Reject dangerous keys
				if (f === '__proto__' || f === 'constructor') {
					throw new Error('Field name is not allowed for security reasons');
