					throw new Error('Field name cannot contain dot, dollar, or slash');
				}

				// Validate increment is a safe integer
				if (!Number.isSafeInteger(value)) {
					throw new TypeError('Increment value must be a safe integer');
				}

				// Normalize field for MongoDB
				const normalizedField = helpers.fieldToString(f);

				incObject[normalizedField] = value;
			}

			// Save the update entry
