		const collection = module.client.collection('objects');

		for (const { key, incObject } of validatedUpdates) {
			try {
				await collection.findOneAndUpdate(
					{ _key: key },
					{ $inc: incObject },
					{ upsert: true }
				);
				succeededKeys.push(key);
			} catch (err) {
				// Skip this key, continue to next
			}
		}

		// Invalidate cache for succeeded keys
		if (succeededKeys.length) {
			cache.del(succeededKeys);
		}
	};
'''

